#!/usr/bin/env python3
# Some portions generated by Codex. Untimed diagnostic copy; production/frozen outputs stay untouched.
from pathlib import Path
p=Path(__file__).resolve().parent
s=(p/'NativeValueMemo.baseline.java').read_text()
s=s.replace('private long totalProbes, totalHits;', '''private long totalProbes, totalHits;
 private long emptyMisses, clearedSameMisses, clearedOtherMisses, liveCollisionMisses, versionMisses, nonNativeMisses;
 private long firstSeenMisses, repeatedMisses, uncacheableReturns;
 private record SeenKey(long id, int mask) {}
 private final java.util.Set<SeenKey> seen = Boolean.getBoolean("diag.memo.seen") ? new java.util.HashSet<>() : null;''')
s=s.replace('''} else {
			value = source.lazyValue(id, mask);''','''} else {
   if (slot < 0 || references[slot] == null) emptyMisses++;
   else if (value == null) {
    if (ids[slot] == id && masks[slot] == mask) clearedSameMisses++; else clearedOtherMisses++;
   } else if (ids[slot] != id || masks[slot] != mask) liveCollisionMisses++;
   else if (!(value instanceof LmdbValue)) nonNativeMisses++;
   else versionMisses++;
   if (seen != null) { if (seen.add(new SeenKey(id, mask))) firstSeenMisses++; else repeatedMisses++; }
			value = source.lazyValue(id, mask);''')
s=s.replace('''references[slot] = new WeakReference<>(value);
			}''','''references[slot] = new WeakReference<>(value);
			} else { uncacheableReturns++; }''')
s=s.replace('''if (!reported) {
			PROBES''','''if (!reported) {
   long missCount=totalProbes-totalHits;
   long classified=emptyMisses+clearedSameMisses+clearedOtherMisses+liveCollisionMisses+versionMisses+nonNativeMisses;
   if (classified != missCount) throw new AssertionError("Diagnostic miss accounting mismatch");
   if (seen != null && firstSeenMisses+repeatedMisses != missCount) throw new AssertionError("Seen-key accounting mismatch");
   System.out.println("MEMO_DIAGNOSTICS probes="+totalProbes+" hits="+totalHits+" misses="+missCount
    +" empty="+emptyMisses+" clearedSame="+clearedSameMisses+" clearedOther="+clearedOtherMisses
    +" liveCollision="+liveCollisionMisses+" version="+versionMisses+" nonNative="+nonNativeMisses
    +" uncacheable="+uncacheableReturns+" exactSeen="+(seen!=null)+" firstSeen="+firstSeenMisses+" repeatedMiss="+repeatedMisses
    +" capacity="+(references==null?0:references.length)+" source="+(source==null?"null":source.getClass().getName()));
			PROBES''')
assert 'MEMO_DIAGNOSTICS' in s and 'emptyMisses++' in s
(p/'source/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeValueMemo.java').write_text(s)
base=(p.parent/'workbench-e2e/run.py').read_text()
base=base.replace("a=p.parse_args()", "p.add_argument('--seen',action='store_true');a=p.parse_args()")
base=base.replace("libs=sorted((d/'runtime/BOOT-INF/lib').glob('*.jar'))", "lmdb=root/'experiments/overlay/memo-diagnosis/diagnostic-classes'\nlibs=sorted((d/'runtime/BOOT-INF/lib').glob('*.jar'))")
base=base.replace("cmd=[str(java)","flags['diag.memo.seen']=str(a.seen).lower()\ncmd=[str(java)")
base=base.replace("result['witnessesPassed']=True;", "assert after['org.eclipse.rdf4j.sail.lmdb.LmdbStore'].endswith('/memo-diagnosis/diagnostic-classes/'),after\n result['witnessesPassed']=True;")
(p/'run-diagnostic.py').write_text(base)
